// Parse request body
const body = $input.item.json.body || {};
const queryParams = $input.item.json.query || {};

// Extract parameters from request
const webhookUrl = body.webhook_url || queryParams.webhook_url || $env.GITHUB_WEBHOOK_URL || 'https://localhost/webhook/github';
const skipFunnel = body.skip_funnel === 'true' || queryParams.skip_funnel === 'true';
const outputJson = body.output_json === 'true' || queryParams.output_json === 'true';

return {
  json: {
    webhook_url: webhookUrl,
    skip_funnel: skipFunnel,
    output_json: outputJson,
    configure_github: true,
    timestamp: new Date().toISOString()
  }
};

// Validate environment variables
const envVars = [
  'GH_WEBHOOK_SECRET',
  'GH_APP_ID',
  'GH_APP_SEC',
  'GH_APP_INSTALLATION_ID'
];

const missing = [];
const present = [];

for (const key of envVars) {
  const value = $env[key];
  if (value && value !== '' && value !== 'changeme') {
    present.push(key);
  } else {
    missing.push(key);
  }
}

return {
  json: {
    valid: missing.length === 0,
    missing: missing,
    present: present,
    webhook_url: $json.webhook_url
  }
};

// Build command for Python script execution
const webhookUrl = $json.webhook_url;
const skipFunnel = $json.skip_funnel;
const outputJson = $json.output_json;

// Build command arguments
let cmdArgs = ['--configure-github'];

if (webhookUrl && webhookUrl !== 'https://localhost/webhook/github') {
  cmdArgs.push(`--webhook-url`, webhookUrl);
}

if (skipFunnel) {
  cmdArgs.push('--skip-funnel');
}

if (outputJson) {
  cmdArgs.push('--output-json');
}

// Construct full command (will be executed via container exec or HTTP)
const command = `python tools/github_webhook_auto_config.py ${cmdArgs.join(' ')}`;

return {
  json: {
    command: command,
    args: cmdArgs,
    webhook_url: webhookUrl
  }
};

// Execute the Python script via container exec or subprocess
// This function prepares the execution context

const command = $json.command;
const webhookUrl = $json.webhook_url;

// For container-based execution, we'll call an HTTP endpoint
// that runs the script inside the container
return {
  json: {
    endpoint: '/api/scripts/execute',
    method: 'POST',
    body: {
      script: 'github_webhook_auto_config.py',
      args: ['--configure-github', `--webhook-url`, webhookUrl, '--output-json']
    },
    webhook_url: webhookUrl
  }
};

// Parse the result from script execution
const data = $input.item.json;

// Determine success based on response
const success = data.success === true || data.status === 'success';
const githubConfigured = data.github_configured === true;

return {
  json: {
    success: success,
    webhook_secret_set: data.webhook_secret_set === true,
    github_configured: githubConfigured,
    message: data.message || 'Configuration completed',
    error: data.error || null,
    timestamp: new Date().toISOString()
  }
};

// Prepare NATS event for successful configuration
const data = $json;

const natsEvent = {
  id: $node.id,
  topic: 'github.webhook.configured.v1',
  ts: data.timestamp,
  version: 'v1',
  source: 'n8n-github-webhook-config',
  payload: {
    success: true,
    github_configured: data.github_configured,
    webhook_secret_set: data.webhook_secret_set,
    message: data.message
  },
  correlation_id: $node.id,
  parent_id: null
};

return {
  json: {
    nats_subject: natsEvent.topic,
    nats_payload: natsEvent,
    status: 'configured',
    message: data.message
  }
};

// Prepare NATS event for failed configuration
const data = $json;

const natsEvent = {
  id: $node.id,
  topic: 'github.webhook.failed.v1',
  ts: data.timestamp,
  version: 'v1',
  source: 'n8n-github-webhook-config',
  payload: {
    success: false,
    error: data.error || 'Unknown error',
    message: data.message
  },
  correlation_id: $node.id,
  parent_id: null
};

return {
  json: {
    nats_subject: natsEvent.topic,
    nats_payload: natsEvent,
    status: 'failed',
    error: data.error
  }
};

// NATS Publishing Stub
// Port 4222 is the NATS client protocol (TCP), NOT an HTTP API.
// To publish to NATS from n8n, use one of:
//   1. Install n8n-nodes-nats community node (recommended)
//   2. Deploy a NATS-HTTP bridge service
//   3. Use NATS WebSocket (ws://nats:9222) with a custom node
const subject = $json.nats_subject;
const payload = $json.nats_payload;
console.log(`[NATS-STUB] Would publish to: ${subject}`);
return { json: { nats_published: false, nats_stub: true, nats_subject: subject, nats_payload: payload, status: $json.status, error: $json.error, message: 'NATS publish requires n8n-nodes-nats community node or HTTP bridge' } };

// Prepare Discord notification
const data = $json;
const isSuccess = data.status === 'configured';

const emoji = isSuccess ? '✅' : '❌';
const title = isSuccess ? 'GitHub Webhook Configured' : 'GitHub Webhook Configuration Failed';

const embed = {
  title: `${emoji} ${title}`,
  description: isSuccess 
    ? 'GitHub App webhook has been configured successfully.'
    : `Failed to configure GitHub App webhook: ${data.error || 'Unknown error'}`,
  color: isSuccess ? 0x00FF00 : 0xFF0000,
  fields: [
    {
      name: 'Status',
      value: isSuccess ? 'Success' : 'Failed',
      inline: true
    },
    {
      name: 'Timestamp',
      value: new Date().toISOString(),
      inline: false
    }
  ],
  footer: {
    text: 'PMOVES.AI GitHub Webhook Auto-Config'
  }
};

return {
  json: {
    webhookUrl: $env.DISCORD_WEBHOOK_URL || 'https://discord.com/api/webhooks/placeholder',
    payload: {
      username: 'PMOVES GitHub Config',
      avatar_url: 'https://github.githubassets.com/images/modules/logos_page/GitHub-Mark.png',
      embeds: [embed]
    }
  }
};

// Return error response for missing environment variables
const missing = $json.missing || [];

return {
  json: {
    success: false,
    error: 'Missing required environment variables',
    missing: missing,
    message: `Please configure: ${missing.join(', ')}`
  }
};
